param([int]$IntervalSeconds=45,[int]$StaleAfterSeconds=720)
# P3_AGENT_WATCH_RETIRED 2026-09-05: every hard-coded worker root below is gone and current liveness
# is established from live MCP/worker evidence. Keep the historical body below for provenance, but
# never restart this obsolete recursive scanner from the still-registered logon task.
$base='C:\Users\Lauri\AppData\Local\P3AgentWatch'
@{generated_at=[DateTimeOffset]::UtcNow.ToString('o');retired=$true;reason='configured worker roots retired; use current live activity evidence'} | ConvertTo-Json | Set-Content (Join-Path $base 'status.json') -Encoding UTF8
exit 0

$ErrorActionPreference='Continue'
$base='C:\Users\Lauri\AppData\Local\P3AgentWatch'
$statusPath=Join-Path $base 'status.json'; $logPath=Join-Path $base 'watch.log'
$workers=@(
@{id='GPT-1';root='C:\Users\Lauri\AppData\Local\Temp\p3-worker-gpt1'},
@{id='GPT-2';root='C:\Users\Lauri\AppData\Local\Temp\p3-worker-gpt2'},
@{id='GPT-3';root='C:\Users\Lauri\AppData\Local\Temp\p3-worker-gpt3'},
@{id='GPT-4';root='C:\Users\Lauri\AppData\Local\Temp\p3-worker-gpt4'},
@{id='GPT-5';root='C:\Users\Lauri\AppData\Local\Temp\p3-worker-gpt5'},
@{id='CODEX-A';root='C:\Users\Lauri\AppData\Local\Temp\p3-v2-quality-recovery'},
@{id='CODEX-B';root='C:\Users\Lauri\AppData\Local\Temp\p3-gpt3-v2-04c1-ai'},
@{id='CODEX-C';root='C:\Users\Lauri\AppData\Local\Temp\p3-gpt1-survival-20260820-1159'})
$mem=@{}; $lastState=@{}
function Newest([string]$r){
  $m=0L
  foreach($d in @('Source','Plugins\P3','scripts','docs','Config','.github','Content\Python','Saved\AgentRuns')){
    $p=Join-Path $r $d; if(!(Test-Path $p)){continue}
    Get-ChildItem $p -File -Recurse -ErrorAction SilentlyContinue | Where-Object {$_.FullName -notmatch '\\(Binaries|Intermediate|DerivedDataCache)\\'} | ForEach-Object {if($_.LastWriteTimeUtc.Ticks -gt $m){$m=$_.LastWriteTimeUtc.Ticks}}
  }; return $m
}
while($true){
  $now=[DateTimeOffset]::UtcNow
  $procs=@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Select ProcessId,CommandLine)
  $rows=@()
  foreach($w in $workers){
    $pm=@($procs|Where-Object{$_.CommandLine -and $_.CommandLine.IndexOf($w.root,[StringComparison]::OrdinalIgnoreCase)-ge 0})
    $live=$pm.Count-gt 0; $build=@($pm|Where-Object{$_.CommandLine -match '(?i)UnrealEditor|UnrealBuildTool|Build\.bat|AutomationTool|RunUAT|dotnet|cl\.exe|link\.exe'}).Count-gt 0
    $head=(& git -C $w.root rev-parse HEAD 2>$null | Select-Object -First 1); $branch=(& git -C $w.root branch --show-current 2>$null | Select-Object -First 1)
    $dirty=@(& git -C $w.root status --porcelain=v1 2>$null).Count; $tick=Newest $w.root; $sig="$head|$dirty|$tick"
    if(!$mem.ContainsKey($w.id)){$mem[$w.id]=@{sig=$sig;last=$now;ever=$live;initial=$head}} elseif($mem[$w.id].sig-ne$sig){$mem[$w.id].sig=$sig;$mem[$w.id].last=$now}
    if($live){$mem[$w.id].ever=$true}; $idle=[int]($now-$mem[$w.id].last).TotalSeconds
    $final=@(Get-ChildItem (Join-Path $w.root 'Saved\AgentRuns') -Filter '*final*.txt' -File -ErrorAction SilentlyContinue).Count-gt 0
    if(!$live){if($final-and$mem[$w.id].ever){$state='COMPLETE'}elseif($mem[$w.id].ever-and$head-ne$mem[$w.id].initial){$state='EXITED_WITH_PROGRESS'}else{$state='DEAD_OR_IDLE'}}elseif($build){$state='BUILDING_OR_TESTING'}elseif($idle-ge$StaleAfterSeconds){$state='STALE'}else{$state='ACTIVE'}
    $rows+=@{id=$w.id;state=$state;pids=@($pm.ProcessId);branch=$branch;head=$head;dirty=$dirty;idle_seconds=$idle;build_busy=$build;root=$w.root;checked_at=$now.ToString('o')}
    if(!$lastState.ContainsKey($w.id)-or$lastState[$w.id]-ne$state){$line="$($now.ToString('o')) $($w.id) state=$state idle=${idle}s dirty=$dirty head=$head";Add-Content $logPath $line;Write-Host $line;$lastState[$w.id]=$state}
  }
  @{generated_at=$now.ToString('o');stale_after_seconds=$StaleAfterSeconds;workers=$rows}|ConvertTo-Json -Depth 6|Set-Content "$statusPath.tmp" -Encoding UTF8; Move-Item "$statusPath.tmp" $statusPath -Force
  Start-Sleep $IntervalSeconds
}
